update public.site_content_blocks set default_text='As the host, pay one soap to reroll a spa buffs set, compare it with your current buff set, then choose whether to replace it. Your current set remains active during the preview. Rerolling again replaces the preview buffs set.', revision=revision+1 where page_key='events/sparkly-spa.html' and block_key='text-27' and revision=2 and published_text='As the host, pay one soap to reroll a spa buffs set, compare it with your current buff set, then choose whether to replace it. Your current set remains active during the preview. Rerolling again replaces the preview buffs set.' and default_text is distinct from 'As the host, pay one soap to reroll a spa buffs set, compare it with your current buff set, then choose whether to replace it. Your current set remains active during the preview. Rerolling again replaces the preview buffs set.';
