update public.site_content_blocks set default_text='Open your own spa or visit a friend’s spa to give tier IV Tatari temporary buffs. The active effect set can improve combat, reduce Goldrush costs or provide daily benefits. Dreamy Sparkle effects also let you collect new Tatari appearances.', revision=revision+1 where page_key='events/sparkly-spa.html' and block_key='text-3' and revision=2 and published_text='Open your own spa or visit a friend’s spa to give tier IV Tatari temporary buffs. The active effect set can improve combat, reduce Goldrush costs or provide daily benefits. Dreamy Sparkle effects also let you collect new Tatari appearances.' and default_text is distinct from 'Open your own spa or visit a friend’s spa to give tier IV Tatari temporary buffs. The active effect set can improve combat, reduce Goldrush costs or provide daily benefits. Dreamy Sparkle effects also let you collect new Tatari appearances.';
update public.site_content_blocks set default_text='Goldrush MVP rewards provide Spa Soap. Island Goldrush reward is 180, 160, 150 or 140 soaps for league ranks I–IV. 
Game shop also contains packs of 10, 20, 50 and 100 Soaps. Check the in-game shop for prices and availability.', revision=revision+1 where page_key='events/sparkly-spa.html' and block_key='text-5' and revision=2 and published_text='Goldrush MVP rewards provide Spa Soap. Island Goldrush reward is 180, 160, 150 or 140 soaps for league ranks I–IV. 
