Game shop also contains packs of 10, 20, 50 and 100 Soaps. Check the in-game shop for prices and availability.';
update public.site_content_blocks set default_text='Host and guest values above are already the configured buffs. Do not double the owner values again because of the “200% effects” tooltip. Final combat stats also depend on other bonuses.', revision=revision+1 where page_key='events/sparkly-spa.html' and block_key='note-4' and revision=2 and published_text='Host and guest values above are already the configured buffs. Do not double the owner values again because of the “200% effects” tooltip. Final combat stats also depend on other bonuses.' and default_text is distinct from 'Host and guest values above are already the configured buffs. Do not double the owner values again because of the “200% effects” tooltip. Final combat stats also depend on other bonuses.';
update public.site_content_blocks set default_text='@rich-v1:[{"text":"These chance percentage are not the probability of a particular named effect appearing in a complete set. Pity resets, whether opening counts as a draw, and pity carry-over between spa activations are not verified. This pity concerns spa effects, not Sparkle skins."}]', revision=revision+1 where page_key='events/sparkly-spa.html' and block_key='note-6' and revision=2 and published_text='@rich-v1:[{"text":"These chance percentage are not the probability of a particular named effect appearing in a complete set. Pity resets, whether opening counts as a draw, and pity carry-over between spa activations are not verified. This pity concerns spa effects, not Sparkle skins."}]' and default_text is distinct from '@rich-v1:[{"text":"These chance percentage are not the probability of a particular named effect appearing in a complete set. Pity resets, whether opening counts as a draw, and pity carry-over between spa activations are not verified. This pity concerns spa effects, not Sparkle skins."}]';
