update public.site_content_blocks set default_text='@rich-v1:[{"text":"Follow the election rules shown during preparation / goldrush registration day. The in-game descriptions cover a highest-Combat-Power selection and a voting variant. Higher power can affect selection or candidate eligibility to become Goldrush League Leader."}]', revision=revision+1 where page_key='events/island-goldrush.html' and block_key='note-12' and revision=2 and published_text='@rich-v1:[{"text":"Follow the election rules shown during preparation / goldrush registration day. The in-game descriptions cover a highest-Combat-Power selection and a voting variant. Higher power can affect selection or candidate eligibility to become Goldrush League Leader."}]' and default_text is distinct from '@rich-v1:[{"text":"Follow the election rules shown during preparation / goldrush registration day. The in-game descriptions cover a highest-Combat-Power selection and a voting variant. Higher power can affect selection or candidate eligibility to become Goldrush League Leader."}]';
update public.site_content_blocks set default_text='@rich-v1:[{"text":"The main goal is to build your league''s point production by claiming tiles and clams across the six configured days. Coordinate a strategy with your league, choose useful routes and high-value tiles, and capture or retake tiles effectively. Attacks contain individual opponent fights: your Tatari skills and formation decide those fights, while Energy Drinks cover the battle cost."}]', revision=revision+1 where page_key='events/island-goldrush.html' and block_key='text-3' and revision=2 and published_text='@rich-v1:[{"text":"The main goal is to build your league''s point production by claiming tiles and clams across the six configured days. Coordinate a strategy with your league, choose useful routes and high-value tiles, and capture or retake tiles effectively. Attacks contain individual opponent fights: your Tatari skills and formation decide those fights, while Energy Drinks cover the battle cost."}]' and default_text is distinct from '@rich-v1:[{"text":"The main goal is to build your league''s point production by claiming tiles and clams across the six configured days. Coordinate a strategy with your league, choose useful routes and high-value tiles, and capture or retake tiles effectively. Attacks contain individual opponent fights: your Tatari skills and formation decide those fights, while Energy Drinks cover the battle cost."}]';
update public.site_content_blocks set default_text='@rich-v1:[{"tag":"strong","children":[{"text":"Energy Drinks / Cans"}]},{"text":" are the battle resource used to boost your Tatari in Goldrush. The amount allocated determines your boost level. Energy Drinks expire after the event ends (Day VI)."}]', revision=revision+1 where page_key='events/island-goldrush.html' and block_key='text-4' and revision=2 and published_text='@rich-v1:[{"tag":"strong","children":[{"text":"Energy Drinks / Cans"}]},{"text":" are the battle resource used to boost your Tatari in Goldrush. The amount allocated determines your boost level. Energy Drinks expire after the event ends (Day VI)."}]' and default_text is distinct from '@rich-v1:[{"tag":"strong","children":[{"text":"Energy Drinks / Cans"}]},{"text":" are the battle resource used to boost your Tatari in Goldrush. The amount allocated determines your boost level. Energy Drinks expire after the event ends (Day VI)."}]';
