update public.site_content_blocks set default_text='@rich-v1:[{"text":"Ownership and defender counts update from the server while attacks are happening. The game records the credited capturer separately from kill MVP. For mining tiles, the in-game text describes league kill totals deciding kill MVP; however last-hit determines who capture the tile."}]', revision=revision+1 where page_key='events/island-goldrush.html' and block_key='note-7' and revision=2 and published_text='@rich-v1:[{"text":"Ownership and defender counts update from the server while attacks are happening. The game records the credited capturer separately from kill MVP. For mining tiles, the in-game text describes league kill totals deciding kill MVP; however last-hit determines who capture the tile."}]' and default_text is distinct from '@rich-v1:[{"text":"Ownership and defender counts update from the server while attacks are happening. The game records the credited capturer separately from kill MVP. For mining tiles, the in-game text describes league kill totals deciding kill MVP; however last-hit determines who capture the tile."}]';
update public.site_content_blocks set default_text='@rich-v1:[{"tag":"strong","children":[{"text":"Skipping the animation does not create extra hits."}]},{"text":" Skip goes straight to the settlement display for the server-provided fight records. It can get you back to the controls sooner, but no client rule establishes that it changes hit order or guarantees last-hit. The exact ordering and tie-breakers for simultaneous attacks are server-controlled and are not exposed in the game data."}]', revision=revision+1 where page_key='events/island-goldrush.html' and block_key='note-8' and revision=2 and published_text='@rich-v1:[{"tag":"strong","children":[{"text":"Skipping the animation does not create extra hits."}]},{"text":" Skip goes straight to the settlement display for the server-provided fight records. It can get you back to the controls sooner, but no client rule establishes that it changes hit order or guarantees last-hit. The exact ordering and tie-breakers for simultaneous attacks are server-controlled and are not exposed in the game data."}]' and default_text is distinct from '@rich-v1:[{"tag":"strong","children":[{"text":"Skipping the animation does not create extra hits."}]},{"text":" Skip goes straight to the settlement display for the server-provided fight records. It can get you back to the controls sooner, but no client rule establishes that it changes hit order or guarantees last-hit. The exact ordering and tie-breakers for simultaneous attacks are server-controlled and are not exposed in the game data."}]';
update public.site_content_blocks set default_text='@rich-v1:[{"tag":"strong","children":[{"text":"One trainer and one tile defender are not the same permanent slot."}]},{"text":" An attack can contain several opponent fights. Which opponent appears is supplied randomly by the server. The random names floating in the map animation are decorative; use the actual battle records to check who you fought. You may fought same trainer on single attack."}]', revision=revision+1 where page_key='events/island-goldrush.html' and block_key='note-9' and revision=2 and published_text='@rich-v1:[{"tag":"strong","children":[{"text":"One trainer and one tile defender are not the same permanent slot."}]},{"text":" An attack can contain several opponent fights. Which opponent appears is supplied randomly by the server. The random names floating in the map animation are decorative; use the actual battle records to check who you fought. You may fought same trainer on single attack."}]' and default_text is distinct from '@rich-v1:[{"tag":"strong","children":[{"text":"One trainer and one tile defender are not the same permanent slot."}]},{"text":" An attack can contain several opponent fights. Which opponent appears is supplied randomly by the server. The random names floating in the map animation are decorative; use the actual battle records to check who you fought. You may fought same trainer on single attack."}]';
update public.site_content_blocks set default_text='@rich-v1:[{"tag":"strong","children":[{"text":"6 appointment actions per day."}]},{"text":" Officer appointments and transferring league leadership share this limit. Removing a title completely does not consume an action. The in-game rules also describe possible automatic league leader transfer after more than 24 hours of inactivity."}]', revision=revision+1 where page_key='events/island-goldrush.html' and block_key='note-10' and revision=2 and published_text='@rich-v1:[{"tag":"strong","children":[{"text":"6 appointment actions per day."}]},{"text":" Officer appointments and transferring league leadership share this limit. Removing a title completely does not consume an action. The in-game rules also describe possible automatic league leader transfer after more than 24 hours of inactivity."}]' and default_text is distinct from '@rich-v1:[{"tag":"strong","children":[{"text":"6 appointment actions per day."}]},{"text":" Officer appointments and transferring league leadership share this limit. Removing a title completely does not consume an action. The in-game rules also describe possible automatic league leader transfer after more than 24 hours of inactivity."}]';
update public.site_content_blocks set default_text='@rich-v1:[{"text":"The game calculates the next attack’s Energy Drink cost using your daily attack count plus one. After 10 counted daily attacks, the next attack uses the exhaustion rate cost modifier."}]', revision=revision+1 where page_key='events/island-goldrush.html' and block_key='text-21' and revision=2 and published_text='@rich-v1:[{"text":"The game calculates the next attack’s Energy Drink cost using your daily attack count plus one. After 10 counted daily attacks, the next attack uses the exhaustion rate cost modifier."}]' and default_text is distinct from '@rich-v1:[{"text":"The game calculates the next attack’s Energy Drink cost using your daily attack count plus one. After 10 counted daily attacks, the next attack uses the exhaustion rate cost modifier."}]';
update public.site_content_blocks set default_text='@rich-v1:[{"tag":"strong","children":[{"text":"Kills and daily attacks are separate counters."}]},{"text":" One attack can show several opponent fights. The client receives the daily counter from the server. Do not assume 11 kills automatically means +20% exhaustion."}]', revision=revision+1 where page_key='events/island-goldrush.html' and block_key='note-13' and revision=2 and published_text='@rich-v1:[{"tag":"strong","children":[{"text":"Kills and daily attacks are separate counters."}]},{"text":" One attack can show several opponent fights. The client receives the daily counter from the server. Do not assume 11 kills automatically means +20% exhaustion."}]' and default_text is distinct from '@rich-v1:[{"tag":"strong","children":[{"text":"Kills and daily attacks are separate counters."}]},{"text":" One attack can show several opponent fights. The client receives the daily counter from the server. Do not assume 11 kills automatically means +20% exhaustion."}]';
update public.site_content_blocks set default_text='@rich-v1:[{"text":"Tatari attacks, skills, buffs, debuffs, defense and elemental matchups determine the fight. Goldrush uses PvP Arena Factor and the 0.8 / 1.2 elemental factors. Selected Energy Drinks boosts ATK and HP and no DEF bonus."}]', revision=revision+1 where page_key='events/island-goldrush.html' and block_key='text-23' and revision=2 and published_text='@rich-v1:[{"text":"Tatari attacks, skills, buffs, debuffs, defense and elemental matchups determine the fight. Goldrush uses PvP Arena Factor and the 0.8 / 1.2 elemental factors. Selected Energy Drinks boosts ATK and HP and no DEF bonus."}]' and default_text is distinct from '@rich-v1:[{"text":"Tatari attacks, skills, buffs, debuffs, defense and elemental matchups determine the fight. Goldrush uses PvP Arena Factor and the 0.8 / 1.2 elemental factors. Selected Energy Drinks boosts ATK and HP and no DEF bonus."}]';
update public.site_content_blocks set default_text='@rich-v1:[{"text":"After combat, a separate calculation uses the enemy side''s recorded total damage relative to your formation''s total battle maximum HP. This is cumulative damage, not damage per second or opponent''s total ATK."}]', revision=revision+1 where page_key='events/island-goldrush.html' and block_key='text-24' and revision=2 and published_text='@rich-v1:[{"text":"After combat, a separate calculation uses the enemy side''s recorded total damage relative to your formation''s total battle maximum HP. This is cumulative damage, not damage per second or opponent''s total ATK."}]' and default_text is distinct from '@rich-v1:[{"text":"After combat, a separate calculation uses the enemy side''s recorded total damage relative to your formation''s total battle maximum HP. This is cumulative damage, not damage per second or opponent''s total ATK."}]';
